(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["en"] = {"ui":{"skip":"Skip to content","back":"← Back to AI-gile","lang.button":"Language: {name}","lang.dialog":"Choose a language","lang.search":"Search languages","lang.none":"No language matches","lang.notYet":"{name} is not translated yet","theme.aria":"Switch between light and dark theme","theme.toLight":"Switch to light theme","theme.toDark":"Switch to dark theme","words.underline":"Underline these words on the page","words.underlineHelp":"Hover or tap a dotted word to see what it means.","index.title":"AI-gile: your AI dev team, on one board","index.description":"AI-gile is a kanban board for AI coding teams. They work while you sleep; you get one short pile of things to decide, test and accept.","hero.logoAlt":"AI-gile board icon","hero.h1.html":"Your AI dev team, on one&nbsp;board.","hero.alpha":"🐣 Closed pre-alpha","hero.alphaTitle":"Early and unfinished: thanks for trying it!","hero.lede":"They build while you sleep. You wake up to one short pile: a few questions, a few things to test, a purple diamond or two. Click, accept, back to your coffee.","dl.windows":"Windows app","dl.browser":"Run it in your browser","dl.soon":"Coming soon","dl.notify":"🔔 Tell me when it opens","dl.notifySmall":"Alpha or beta","hero.secondary":"Agile, but the team never needs a stand-up coffee. (They do stand-ups anyway.)","pitch.h2":"AI-gile in as many words as you like","pitch.lede":"Pick a length, from one word to 144. Each length is its own description, written for that size. Drag the slider or use the arrow keys.","pitch.rangeLabel":"Length in words","pitch.dice":"🎲 another version","pitch.words.one":"{n} word","pitch.words.other":"{n} words","pitch.letters.one":"{n} letter","pitch.letters.other":"{n} letters","pitch.chars.one":"{n} character","pitch.chars.other":"{n} characters","count.line.html.one":"{n} card on the board right now","count.line.html.other":"{n} cards on the board right now","features.aria":"What it does","f.pile.h":"One pile for you","f.pile.html":"<b>For you</b> holds everything waiting on you, across every project: questions, things to test, tasks only a human can do. Your queue says what's next and how long it takes.","f.sleep.h":"Teams that work while you sleep","f.sleep.p":"Each project has a lead and a team of AI agents. Comment on a card and the team wakes up, does the work, and hands it back with steps a tired human can follow.","f.tester.h":"An AI tester checks first","f.tester.p":"Before anything reaches you, a tester follows the steps in a copy of the app and shows what it saw, with a screenshot. Flick through the passed ones and accept in a click.","f.proof.h":"Proof, not promises","f.proof.p":"Every hand-over shows what changed: the files, the diff, the screenshots. No opening every app to see if it's done.","f.chat.h":"Chat with your leads","f.chat.p":"A Discord-style rail: one icon per project, purple diamonds for what needs you. Message a lead an idea; they turn it into cards and a plan, with a ✅ Go button.","f.tidy.h":"Keeps itself tidy","f.tidy.p":"Related cards fold into one, muddled titles get fixed, and a token check keeps the code lean. Fewer things to switch between, less to think about.","f.private.h":"Yours, on your computer","f.private.li1":"The board runs on your own machine and only answers you.","f.private.li2":"Private DMs between people are end-to-end encrypted.","f.private.li3":"No accounts, no trackers, no cookies.","f.lang.h":"In your language","f.lang.p":"Over 120 languages, from Dutch, Welsh and Japanese to pirate, Yoda and Klingon, with a quick switch back to English for the developer words.","f.service.h":"From an idea to a real service","f.service.p":"Built something with AI that people now use? Mark it as a service and the board helps you run it well: uptime checks, a public status page, incidents with a write-up, changes that need a Go, backups checked daily. Help teaches each step as you go.","tl.aria":"Timeline from the first conversation to the roadmap","tl.h2":"From the first chat to what's next","tl.lede":"Real dates and times, in your own time zone. After today it's the plan, with no dates promised.","tl.today":"Today","tl.planned":"planned","tl.cards.one":"{n} card","tl.cards.other":"{n} cards","join.h2":"Join in","join.lede":"AI-gile is being built by a small human and a large number of patient agents. It's private for now, in a closed alpha with friends. Want a go when it opens up?","join.btn":"Register interest","join.small":"We'll email you, nothing else","footer.tag":"AI-gile. No trackers, no cookies, no stand-up coffee.","footer.licence":"Business licence","footer.status":"Status","footer.privacy":"What we keep","form.sending":"Sending…","form.failed":"That didn't work: try again later.","form.offline":"Couldn't reach AI-gile: try again later.","form.keep":"We only use this to reply to you, then delete it. No trackers, no cookies.","form.keepLink":"What we keep","interest.title":"AI-gile: tell me when the alpha opens","interest.description":"Leave your email to hear when AI-gile's closed alpha or beta opens.","interest.h1":"🔔 Tell me when it opens","interest.lede":"AI-gile is in closed pre-alpha. Leave your email and we'll write once, when there's a place for you.","interest.email":"Your email","interest.which":"Which test?","interest.alpha":"Closed alpha: early, rough, lots of changes","interest.beta":"Beta: steadier, later","interest.both":"Either, whichever comes first","interest.submit":"Put me on the list","interest.thanks":"Thanks! You're on the list.","licence.title":"AI-gile: business licence","licence.description":"Using AI-gile in your business? Apply for a free business licence.","licence.h1":"📜 Business licence","licence.lede":"Using AI-gile at work? Tell us who you are and what you do. If it does some good, the licence is free.","licence.company":"Company","licence.website":"Website","licence.what":"What you do","licence.how":"How it helps the world","licence.email":"Email","licence.submit":"Apply","licence.thanks":"Thanks! We'll reply by email.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"All quiet","status.intro":"Is AI-gile working right now? This page checks the website, board sharing, calls and the download every 5 minutes.","status.up":"Working (answered in {ms} ms)","status.slow":"Didn't answer the last check, trying again","status.down":"Down: didn't answer the last two checks","status.svc.web":"Website","status.svc.web.offers":"This site: what AI-gile is, and the interest form","status.svc.boards":"Board sharing","status.svc.boards.offers":"Public boards, messages between friends and invites","status.svc.calls":"Calls","status.svc.calls.offers":"Voice, video and screen share in AI-gile","status.svc.download":"Download","status.svc.download.offers":"The Windows installer and invite links","status.checking":"Checking…","status.offline":"Can't reach the status service right now (retrying)","status.updated":"updated {ago}","status.justNow":"just now","status.min":"{n} min ago","status.hours":"{n} h ago","status.days":"{n} d ago","privacy.title":"AI-gile: what we keep","privacy.h1":"What we keep","privacy.lede":"Short version: only what you send us, and not for long.","privacy.only":"Only what you send us: what you type into a form, like your email. Nothing else about you.","privacy.sealed":"It is sealed so our server can't read it: in your browser before it leaves (on an older browser, the moment it arrives). Only our own board can open it.","privacy.server":"It is deleted from the server as soon as it reaches our board. Anything still there after 30 days is deleted anyway.","privacy.board":"We keep it on our board only until we've replied to you, then delete it there too.","privacy.none":"No trackers, no cookies, no analytics.","privacy.local":"Your language and light or dark choice stay in your own browser. They are never sent to us.","privacy.ask":"Want it gone sooner? Reply to our email and say so.","live.h2":"Watch it being built, live","live.caption":"Every card is hidden: you see the shape of the work, not the words.","live.watching.one":"live: {n} watching","live.watching.other":"live: {n} watching","live.last.now":"Last card moved just now","live.last.min.one":"Last card moved {n} min ago","live.last.min.other":"Last card moved {n} min ago","live.last.hour.one":"Last card moved {n} hour ago","live.last.hour.other":"Last card moved {n} hours ago","live.last.day.one":"Last card moved {n} day ago","live.last.day.other":"Last card moved {n} days ago","live.offline":"The live board is taking a breather. Check back soon.","live.cols":"Backlog|To do|In progress|Team checking|For you to test|For the team|Done"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Delegated."]},{"n":2,"texts":["Robot kanban.","Agents, organised.","Ideas, built."]},{"n":3,"texts":["Kanban for robots.","Ideas become features.","Free agent kanban."]},{"n":5,"texts":["Kanban board run by agents.","You write cards. Agents build.","Free, local, tested, slightly silly."]},{"n":8,"texts":["A free kanban board where AI agents work.","Write an idea. Agents build it. You accept.","Agile for one human and many patient robots."]},{"n":13,"texts":["A kanban board on your computer where AI agents pick up the cards.","Write an idea. A team of agents builds it. A tester checks it.","Free, no accounts, no trackers: a board, some robots, and you in charge."]},{"n":21,"texts":["AI-gile is a kanban board for working with AI coding agents. They pick up the cards; you test and accept them.","Each project gets a lead and a team of AI agents. Comment on any card and the team gets to work.","A free, personal to-do board that runs on your own computer. The workers are robots. The one saying yes is you."]},{"n":34,"texts":["You put ideas on a board. A team of AI agents turns them into working features, tests them, and hands them back with steps to try. Nothing counts as done until you say so.","AI-gile is a homemade kanban board that Rich built with a lot of help from the agents it now manages. It is free, runs on your computer, and is shared with friends, not sold.","Picture a normal kanban board, with columns from Backlog to Done, except the cards are picked up by AI agents. They report progress, ask questions when stuck, and always wait for your thumbs up."]},{"n":55,"texts":["AI-gile is a kanban board where the team is made of AI agents. Each project has a lead who plans the work and helpers who build it. When a feature is ready, an AI tester tries it and takes a screenshot, then it lands in your pile. Accept it, or comment and they rework it.","It started as one person's way of keeping track of lots of AI coding sessions at once, and grew into a proper board. It runs on your machine, needs no account, and has no trackers. It is free for friends and anyone curious. It is also unfinished, so expect rough edges and the odd surprise.","Here is the honest version. You still have to have the ideas, and you still have to check the results. What AI-gile does is everything in between: it keeps the cards in order, wakes the right agent when you comment, shows exactly what changed, and keeps all of it in one short pile for you."]},{"n":89,"texts":["AI-gile is a free kanban board that you run on your own computer. Instead of people, each project has a team of AI agents: a lead who turns your ideas into cards and a plan, and helpers who pick the cards up in priority order. When something is built, an AI tester follows the test steps and shows you what it saw. Then it waits in one pile marked For you. You accept it, or you comment and the team has another go. Nothing ever reaches Done without you.","Some features you might not expect. A night watch keeps the To do column topped up while you sleep, choosing cards that don't need an answer from you. A token counter shows how much the agents have used today and this week, and No Token Mode tells them to stop spending. You can message friends, and private messages are end-to-end encrypted. The board speaks about 120 languages, including Dutch, Flemish, pirate and Klingon. None of it costs a penny, and nobody is trying to sell it to you either.","AI-gile is a small, personal project, not a company. Rich wanted to look after several AI coding projects without opening every app to check on them, so he and the agents built a board for it, then used the board to build the rest of itself. It is in closed pre-alpha, which means it works, mostly, for a handful of friends. There is no pricing page, no newsletter and no growth plan. If it sounds useful, you can ask to try it when it opens up a little more."]},{"n":144,"texts":["AI-gile is a kanban board for one human and a lot of AI agents. It runs on your own computer and it is completely free. You add projects, and each project gets a lead and a small team. You chat with the lead, a bit like Discord, and describe an idea; the lead turns it into cards and a plan, then waits for you to press Go. The team works through the cards in priority order, using a simple command line made for language models. Before anything comes back to you, an AI tester follows the steps in a copy of the app and attaches a screenshot. Finished work lands in your pile with the changed files and the diff. You accept it, or you leave a comment and the team wakes up and tries again. Only you can move a card to Done.","A day with AI-gile, roughly. In the evening you leave a few comments: this button is in the wrong place, that list should be sorted, could we have a dark mode. You go to bed. The agents read the comments, make the changes, test them and hand them back to you. If To do runs dry, the night watch fills it from the backlog with cards that need no answer from you. In the morning there is one short pile: a couple of questions and a few things to try, each with steps a sleepy person can follow and a screenshot of it working. You click through, accept the good ones and send back the rest. A token counter shows what it all used, and No Token Mode is there for lean weeks. Then you have breakfast, which the agents cannot help with yet.","First, what AI-gile is not. It is not a startup, it is not for sale, and nobody is collecting your data. It is a free board that runs on your computer, with no accounts, no trackers and no cookies. What it is: one tidy place to see every AI coding project at once, with a team of agents doing the cards and you making the decisions. It folds related cards together, fixes muddled titles, and keeps an eye on how lean the code stays. It speaks about 120 languages, from Dutch and Flemish to pirate and Klingon. Friends can message each other, privately and encrypted. It was built by Rich and a large number of patient agents, mostly using itself. It is in closed pre-alpha, so it is rough in places. If it sounds like fun, ask nicely and you might get in early."]}],"quips":{"1":"One word. Bold. Possibly too bold.","3":"Three words. Already more honest than most product pages.","8":"Eight words. Still shorter than a stand-up.","21":"The lengths are story points, by the way. Of course they are.","55":"Fifty-five words. Two cards got finished while you read that.","144":"That's the long one. There is no 233. The agents have gone to bed."}},"timeline":{"first-idea.name":"The first idea","first-idea.line":"The very first conversation, before any code existed.","first-board.name":"First board","first-board.line":"A board that tracks its own build: cards, columns, drag and drop, projects.","team-roles.name":"Team and roles","team-roles.line":"Agent profiles, team templates, spaces and who does what.","install.name":"Install and releases","install.line":"A zip a friend can install, self-updates, channels and roll back.","usage-saver.name":"Usage saver","usage-saver.line":"Measure what runs cost, keep the code lean, save your limit.","friends.name":"Friends and sharing","friends.line":"Private DMs, a scrambled relay, invites, roles and shared projects.","languages.name":"Languages","languages.line":"Every screen text in a language file, with Dutch and Flemish first.","ai-tester.name":"AI tester","ai-tester.line":"A tester checks every hand-over first and shows what it saw.","website.name":"The website","website.line":"aigile.lol, the teaser and this timeline.","streaming.name":"Chat and streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, GIFs and emojis.","no-ai.name":"No AI edition","no-ai.line":"A board for people who code without AI, and public boards.","night-watch.name":"Night watch","night-watch.line":"A watchman and Scrum Master keep the teams on task while you sleep.","p-more.name":"Everything else","p-more.line":"Smaller ideas still waiting their turn.","p-android.name":"Phone and Android","p-android.line":"Reach your board from a phone, then a native Android app.","p-release.name":"Alpha and beyond","p-release.line":"Closed alpha, the live site, then beta.","p-languages.name":"More languages","p-languages.line":"More than a hundred languages, and an immersion mode for learners.","p-engines.name":"More AI engines","p-engines.line":"Pick Claude, Codex or Gemini per agent.","p-pro.name":"Pro practice","p-pro.line":"Risk labels, merge gates, incident cards and guard rails.","p-self.name":"Looking after you","p-self.line":"Tired mode, self-care reminders and 4:20.","p-servers.name":"Servers and scale","p-servers.line":"Global server settings, roles and planning for growth.","p-livestream.name":"Streaming extras","p-livestream.line":"Twitch chat, custom emojis and a public live view."},"words":{"button":"📖 Dev words","h":"📖 Words explained","intro":"The words you meet in AI-gile, in plain language: building it, changing it safely, keeping it running for the people who use it, and working as a team with AI.","search":"Search a word…","none":"No word matches that.","close":"Close","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Building it"},{"id":"change","name":"🔀 Changing it safely"},{"id":"run","name":"🛎️ Running a service"},{"id":"team","name":"🤝 Working as a team (and with AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"The project’s folder of code and its full history of commits, usually also kept on GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"A separate line of work in the code, so changes can be made without touching the main version.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"A saved snapshot of the code, with a short note of what changed. You can always go back to one.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sending saved snapshots (commits) from this computer up to GitHub, so they are backed up and shared."},{"id":"merge","g":"build","word":"Merge","text":"Joining a branch’s changes back into the main version."},{"id":"pr","g":"build","word":"Pull request","text":"Asking for a branch’s changes to be checked and merged into the main version.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tidying the code without changing what it does: smaller files, clearer names, less repetition."},{"id":"bug","g":"build","word":"Bug","text":"Something that doesn’t work the way it should.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Trying a finished piece of work to check it does what was asked, before you accept it.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Short for quality assurance: the automatic checks that run before anything goes live. When QA is red, something failed, and it can’t go live until that is fixed.","also":["quality checks"]},{"id":"deploy","g":"change","word":"Deploy","text":"Putting a new version live, for example onto a server where people use it."},{"id":"release","g":"change","word":"Release","text":"A named bundle of finished work that goes live together, with short notes on what changed. 🚀 Releases writes the notes from the done cards.","also":["releases"]},{"id":"rollback","g":"change","word":"Roll back","text":"Going back to the last version that worked when a new one causes trouble. In AI-gile it makes a checklist of the undo steps written on each change.","also":["rollback","roll-back","rolled back"]},{"id":"live","g":"change","word":"Live","text":"The real version that people use, as opposed to a copy for trying things out. Developers also call it production.","also":["production"],"noTip":1},{"id":"change","g":"change","word":"Change","text":"A planned change to something people rely on, written down first: what, why, the risk, when, and how to undo it. Start one with 🔀 Raise a change.","also":["change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Risk","text":"Something that could go wrong, scored on how likely and how bad it would be. ⚠️ Risks keeps them in one list, highest score first, each with a date to look again.","also":["risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"The times when changes may go live, such as a quiet Tuesday evening. Outside a window a change card can’t be finished, unless it is an emergency.","also":["change windows"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"A quick vote just before a change goes live: each person who has to approve says Go or No go. It only goes ahead when they agree.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Waiting for a yes before work starts. A card a friend raises, or a change, waits in ✅ Approvals until you approve or decline it.","also":["approvals"]},{"id":"quiettime","g":"change","word":"Quiet time","text":"A stretch of time, like a stream, a demo or the night, when nothing goes live. The teams keep working and testing, but going live waits until it ends. Elsewhere it is called a change freeze.","also":["quiet times","change freeze"]},{"id":"service","g":"run","word":"Service","text":"Something you built that people rely on, like a website or an app, looked after so it keeps working. Tick “This project is a service” and say what it offers, who uses it and who is on call.","also":["services"]},{"id":"uptime","g":"run","word":"Uptime check","text":"An automatic check, every few minutes, that your service still answers. If it fails several times in a row, AI-gile opens an incident card by itself.","also":["uptime","uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"A public page that shows whether a service is working (green, orange or red) with the latest update, so the people who use it can check instead of asking.","also":["status pages"]},{"id":"incident","g":"run","word":"Incident","text":"Something that is broken for the people using it right now, like the website being down. A 🔥 incident card jumps the queue: getting it working again comes first.","also":["incidents"]},{"id":"major","g":"run","word":"Major incident","text":"A big incident: many people affected, or money or data at risk. One button puts every team on it (swarm), wakes whoever is on call and asks for a status update every 30 minutes.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Being the one who answers when something breaks, even at night. Each service has an on-call team member who is woken first for its incidents.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"How long a card may wait for a first answer, for example an hour for an incident. After that it gets a red clock, so nothing is quietly forgotten. Also called a response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"A short look back after an incident: what happened, what helped and what to change, without blaming anyone. An incident can’t be closed without one.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problem","text":"The hidden cause behind one or more incidents. A 🧩 problem card groups incidents that keep coming back, so the cause is found and fixed for good.","also":["problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"The real reason something broke, not just what you saw going wrong. Fix the root cause and the incident stops coming back.","also":["root causes"]},{"id":"workaround","g":"run","word":"Workaround","text":"A way to keep things working until the real fix is ready, like restarting something when it gets stuck. It is written on the problem card so nobody has to work it out again.","also":["workarounds"]},{"id":"knownerror","g":"run","word":"Known error","text":"A problem whose cause is understood and that has a workaround, but isn’t fixed yet. 🧩 Known errors lists them, so everyone uses the workaround instead of digging again.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Step-by-step instructions for fixing a known kind of trouble, so it is done the same way, quickly, every time. After a big incident the team can propose one for you to OK.","also":["runbooks"]},{"id":"backup","g":"run","word":"Backup","text":"A saved copy of your data from earlier, to fall back on if something is lost or damaged. AI-gile makes a backup of your boards every day.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Restore","text":"Putting data back from a backup. A backup only really counts once you know it can be restored, so it is worth trying now and then.","also":["restored"]},{"id":"backlog","g":"team","word":"Backlog","text":"Ideas and work not planned in yet. Nothing there gets worked on until it moves to To do."},{"id":"sprint","g":"team","word":"Sprint","text":"A short stretch of work (often a week or two) with an agreed set of cards to finish.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"A quick check-in: what each team member did, what they do next, and what is stopping them.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"A board with columns (To do, In progress, Done) where cards move left to right as work happens."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: the most cards a column should hold, so the team finishes things before starting more.","also":["WIP"]},{"id":"dod","g":"team","word":"Definition of Done","text":"The team’s short checklist of what “finished” means, like tested and explained, before a card is handed to you. Its twin, the Definition of Ready, says when a card is clear enough to start.","also":["Definition of Ready"]},{"id":"testpile","g":"team","word":"Test pile","text":"The finished cards waiting for you to try, one after another. Accept one or send it back with a note, and the next one comes up.","also":["test piles"]},{"id":"retro","g":"team","word":"Retro","text":"A look back at how the team works, to agree on one thing to do better. In AI-gile a retro suggests a change to the team’s ways of working, and you say Go or Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"peerreview","g":"team","word":"Peer review","text":"A second pair of eyes: another AI checks each card’s work before it reaches you, so fewer mistakes get through.","also":["code review"]},{"id":"swarm","g":"team","word":"Swarm","text":"All hands on deck: every team drops other work to help on one urgent project until it is sorted. Other projects wait meanwhile.","also":["swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"The one who keeps the work flowing: spots stuck cards, nudges the teams and reminds you of what is waiting. In AI-gile the Lead Scrum Master does this across every project.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"An AI that works on its own on a task: reads the code, makes changes, runs checks, and reports back.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"The unit AI usage is counted in: roughly a few letters of text read or written. Fewer tokens, more of your plan left.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"A small command that runs by itself at a set moment, e.g. when an AI session starts, so the team hears your comments.","also":["hooks"]}]}};
